import {education,abilities} from './express-entry.js';
import {tests,convertScore,applyScores} from './language-tests.js';
import {searchOccupations,teerGroup} from './occupations.js';
import {qualificationGuides} from './qualification-guides.js';
import {scoringSystems} from './systems.js';
let occupationData=[],occupationLoad='loading',occupationQuery='',chosenOccupation=null,occupationMatches=[],activeOccupation=-1;
const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const system=scoringSystems.get('canada-express-entry');let state=system.defaults();
const $=id=>document.getElementById(id),options=(items,value)=>items.map(([v,label])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${label}</option>`).join('');
function qualificationBox(key){const guide=qualificationGuides[key];if(!guide)return '';return `<details class="qualification-box"><summary>${guide.title}</summary>${guide.note?`<p class="qualification-note">${guide.note}</p>`:''}<ul class="qualification-list">${guide.items.map(item=>`<li>${item}</li>`).join('')}</ul>${guide.foot?`<p class="hint">${guide.foot}</p>`:''}<a href="${guide.source}" target="_blank" rel="noopener">Official requirements ↗</a><p class="hint qualification-reminder">Use these criteria to answer the question above. Opening this guide does not change your answer or score.</p></details>`;}
function select(key,label,items,hint='',wide=false){if(['canadian','foreign','spouseCanadian','fswYears'].includes(key))return slider(key,label,items,hint,wide);return `<div class="question ${wide?'wide':''}"><label>${label}<select data-key="${key}" id="${key}">${options(items,state[key])}</select>${hint?`<span class="hint">${hint}</span>`:''}</label>${qualificationBox(key)}</div>`;}
function check(key,label,hint=''){return `<div class="question"><label class="check"><input type="checkbox" data-key="${key}" ${state[key]?'checked':''}><span>${label}${hint?`<small>${hint}</small>`:''}</span></label>${qualificationBox(key)}</div>`;}
const tri=(key,label,hint='')=>select(key,label,[['unknown','Not sure / not answered'],['yes','Yes'],['no','No']],hint,true);
const years=max=>Array.from({length:max+1},(_,i)=>[i,i===0?'None / less than 1 year':`${i}${i===max?'+':''} year${i===1?'':'s'}`]);
function slider(key,label,items,hint='',wide=false){return `<div class="slider-field ${wide?'wide':''}"><label for="${key}">${label}</label><div class="range-heading"><output id="${key}-value" for="${key}">${items[state[key]][1]}</output></div><input type="range" id="${key}" data-key="${key}" min="0" max="${items.length-1}" step="1" value="${state[key]}" aria-valuetext="${items[state[key]][1]}"><div class="range-ends"><span>${items[0][1]}</span><span>${items.at(-1)[1]}</span></div>${hint?`<p class="hint">${hint}</p>`:''}</div>`;}
function benchmarkText(level,fr){return level===null?'Enter a valid score':level===0?'Below '+(fr?'NCLC':'CLB')+' 4':`${fr?'NCLC':'CLB'} ${level===10?'10+':level}`;}
function language(key,title){
 const l=state[key],fr=key.toLowerCase().includes('french'),test=tests[l.test];
 return `<div class="language" id="language-${key}"><div class="language-head"><h3>${title}</h3><span class="tag">${fr?'NCLC':'CLB'} auto-conversion</span></div><label>Test taken<select data-language="${key}" data-mode="test" aria-label="${title} test taken">${options([['','No valid test results'],...Object.entries(tests).filter(([,t])=>t.language===(fr?'french':'english')).map(([id,t])=>[id,t.name])],l.test??'')}</select></label>${test?`<p class="hint">Enter your four scores or drag the sliders to explore a different result.</p>${l.test==='tef'?'<p class="test-notice">Use the <strong>Équivalence ancien score</strong> column on your TEF report, not “Score / 699”.</p>':''}${l.test==='celpip'?'<p class="hint">For a CELPIP result marked M (0–2), enter 0; it earns no CRS language points.</p>':''}<div class="abilities score-inputs">${abilities.map((ability,i)=>{const value=l.scores?.[i]??'',level=convertScore(l.test,i,value);return `<div class="score-input"><label for="${key}-score-${i}">${ability}</label><input id="${key}-score-${i}" type="number" inputmode="${test.step===0.5?'decimal':'numeric'}" data-language="${key}" data-score="${i}" min="${test.min[i]}" max="${test.max[i]}" step="${test.step}" value="${value}" placeholder="Score" aria-label="${title} ${ability} score" aria-describedby="${key}-benchmark-${i}"><input type="range" data-language="${key}" data-score="${i}" min="${test.min[i]}" max="${test.max[i]}" step="${test.step}" value="${level===null?test.min[i]:value}" aria-label="${title} ${ability} score slider"><span class="hint">${test.min[i]}–${test.max[i]}</span><output class="benchmark" id="${key}-benchmark-${i}">${benchmarkText(level,fr)}</output></div>`;}).join('')}</div><p class="hint" id="${key}-completion">${l.complete?'All four scores converted. Language points included.':'Complete all four scores to include this language in your estimate.'}</p>`:'<div class="empty">No language points claimed. Choose your test to enter your scores.</div>'}</div>`;
}
function occupationPicker(){return `<div class="wide occupation-picker"><label for="occupation-search">Find your Canadian occupation</label><input type="search" id="occupation-search" role="combobox" aria-autocomplete="list" aria-controls="occupation-options" aria-expanded="false" aria-describedby="occupation-help" autocomplete="off" placeholder="Type a job title or NOC code, e.g. software engineer" value="${escapeHtml(occupationQuery)}"><div id="occupation-options" role="listbox" aria-label="Matching occupations" hidden></div><p id="occupation-feedback" class="hint" aria-live="polite"></p><div id="occupation-selected">${occupationSelection()}</div><p class="hint" id="occupation-help">Search official NOC 2021 titles, then choose the occupation that matches your duties. A job title alone does not confirm your NOC. You can also select a TEER category manually below.</p></div>`;}
function occupationSelection(){if(!chosenOccupation)return '';const g=chosenOccupation;return `<div class="occupation-selection"><strong>${escapeHtml(g.matchedTitle)}</strong><span>NOC ${g.code} · TEER ${g.teer} · ${escapeHtml(g.title)}</span><a href="https://www23.statcan.gc.ca/imdb/p3VD.pl?Function=getVD&TVD=1322554&CVD=1322870&CPV=${g.code}&CST=01052021&CLV=5&MLV=5" target="_blank" rel="noopener">Review official duties ↗</a>${g.teer>=4?'<span>This occupation is TEER 4/5 and does not qualify as skilled work for CEC.</span>':''}</div>`;}
function closeOccupations(){const list=$('occupation-options');if(list)list.hidden=true;const input=$('occupation-search');if(input){input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}activeOccupation=-1;}
function showOccupations(){
 const input=$('occupation-search'),list=$('occupation-options');if(!input||!list)return;
 occupationMatches=searchOccupations(occupationData,occupationQuery);activeOccupation=-1;
 list.innerHTML=occupationMatches.map((g,i)=>`<div role="option" id="occupation-option-${i}" aria-selected="false" data-occupation="${i}"><strong>${escapeHtml(g.matchedTitle)}</strong><span>NOC ${g.code} · TEER ${g.teer} · ${escapeHtml(g.title)}</span></div>`).join('');
 list.hidden=!occupationMatches.length;input.setAttribute('aria-expanded',String(occupationMatches.length>0));input.removeAttribute('aria-activedescendant');
 $('occupation-feedback').textContent=occupationLoad==='loading'?'Loading official occupation titles…':occupationLoad==='error'?'Occupation data could not load. Use the TEER selector below.':occupationQuery.trim().length<2?'Enter at least two characters.':occupationMatches.length?`${occupationMatches.length} matching occupation groups${occupationMatches.length===12?' shown; refine your search for more specific matches':''}. Use arrow keys and Enter to select.`:'No match found. Try fewer words or a five-digit NOC code.';
}
function chooseOccupation(index){const g=occupationMatches[index];if(!g)return;chosenOccupation=g;occupationQuery=g.matchedTitle;$('occupation-search').value=occupationQuery;state.cecTeer=teerGroup(g.teer);$('cecTeer').value=state.cecTeer;$('occupation-selected').innerHTML=occupationSelection();$('occupation-feedback').textContent=`Selected NOC ${g.code}, TEER ${g.teer}. CEC category updated.`;closeOccupations();results();}
function form(){ $('basic-fields').innerHTML=`<div class="slider-field"><label for="age">Age</label><input data-key="age" id="age" type="number" min="0" max="100" step="1" required value="${state.age}"><input type="range" data-key="age" min="0" max="100" step="1" value="${state.age}" aria-label="Age slider"><div class="range-ends"><span>0</span><span>100 years</span></div></div>${select('spouse','Spouse or common-law partner',[[false,'No / not accompanying / Canadian PR or citizen'],[true,'Accompanying, not Canadian PR or citizen']])}${select('education','Highest completed education',education.map((e,i)=>[i,e]),'For multiple credentials, at least one must be 3+ years. Professional degrees must be in an IRCC-eligible licensed field.',true)}<div class="wide">${check('educationValid','Canadian credential or valid immigration ECA','Foreign education requires an Educational Credential Assessment less than 5 years old. Clear this to exclude unassessed education points.')}</div>`;
 $('language-fields').innerHTML=language('english','English')+language('french','French')+'<p class="hint">Select only approved tests taken less than 2 years ago. CLB/NCLC 10+ is grouped because higher levels do not add CRS points. No IELTS Academic or One Skill Retake.</p>';
 $('remaining-fields').innerHTML=`<section id="experience"><div class="section-title"><span class="number">03</span><h2>Experience & additional points</h2></div><div class="fields">${select('canadian','Canadian skilled work',years(5),'Qualifying TEER 0–3 work in the last 10 years. Paid, authorized work while physically in Canada; exclude full-time student and self-employed work, unless an IRCC exception applies.')}${select('foreign','Foreign skilled work',years(3),'Qualifying paid TEER 0–3 experience outside Canada in the last 10 years.')}${select('canadianStudy','Eligible Canadian education',[[0,'None / does not meet requirements'],[15,'One- or two-year credential'],[30,'3+ years / master’s / professional / doctorate']],'Choose only qualifying study: generally at least 8 months full-time and physically in Canada. Language-majority programs and return-home scholarships are excluded; IRCC exceptions may apply.',true)}</div>${check('sibling','Qualifying sibling in Canada','Your or your accompanying spouse’s sibling, age 18+, living in Canada as a citizen or permanent resident.')}${check('nomination','Accepted Express Entry provincial nomination','A nomination linked to Express Entry adds 600 points. Additional points are capped at 600 in total.')}${check('certificate','Canadian certificate of qualification in a skilled trade','Issued by a provincial, territorial or federal authority; not an ordinary college trade diploma.')}</section>${state.spouse?`<section><div class="section-title"><span class="number">+</span><h2>Accompanying spouse</h2></div><div class="fields">${select('spouseEducation','Assessed / Canadian education',education.map((e,i)=>[i,e]),'Select none if a foreign credential has no valid ECA.')}${select('spouseCanadian','Qualifying Canadian work',years(5))}</div>${language('spouseEnglish','Spouse · English')}${language('spouseFrench','Spouse · French')}<p class="hint">Only the higher-scoring spouse language counts.</p></section>`:''}<section><div class="section-title"><span class="number">✓</span><h2>Program eligibility questions</h2></div><p>Work requirements have different time windows. Confirm each one independently.</p><div class="fields">${tri('outsideQuebec','Do you plan to settle outside Quebec?')}${tri('funds','Do you meet the current settlement-funds requirement?','Use IRCC’s current amount for your family size. A qualifying job offer plus authorization to work can provide an exemption for FSW/FST. CEC does not require settlement funds.')}</div>${check('authorized','Currently authorized to work in Canada')}<h3 class="subheading">Canadian Experience Class (CEC)</h3><div class="fields">${occupationPicker()}${select('cecTeer','TEER category of qualifying Canadian work',[['unknown','Select an occupation or TEER category'],['01','TEER 0 or 1'],['23','TEER 2 or 3'],['45','TEER 4 or 5 — not qualifying for CEC']],'Use the higher language threshold if relying on TEER 0/1 work.',true)}${tri('cecWork','At least 1 year of qualifying Canadian work in the last 3 years?','At least 1,560 hours over 12 months, maximum 30 hours/week counted; paid, authorized work in Canada, matching the NOC lead statement and most duties. Exclude full-time student and self-employed work (physician exceptions may apply).')}</div><h3 class="subheading">Federal Skilled Worker (FSW)</h3><div class="fields">${tri('fswWork','At least 1 continuous year in the same skilled occupation?','Paid TEER 0–3 work in your primary NOC within the last 10 years, matching its lead statement and most duties. At least 1,560 hours over 12 months; equivalent part-time work can count.')}${select('fswYears','Total qualifying skilled work in the last 10 years',years(6),'Canada and abroad combined, without double-counting overlapping work.',true)}</div>${check('fswOffer','Job offer meets IRCC’s FSW arranged-employment rules','At least one year, paid, full-time, non-seasonal TEER 0–3 work plus the applicable LMIA or work-permit exemption conditions. Review the official FSW source below; an ordinary offer alone is not enough.')}<details><summary>FSW adaptability factors (up to 10 points)</summary>${check('adaptWork','At least 1 year of authorized full-time skilled work in Canada')}${check('adaptStudy','At least 2 academic years of qualifying full-time study in Canada','Program at least 2 years, 15+ class hours/week, good academic standing.')}${check('relative','Qualifying adult relative in Canada','You or your accompanying spouse: parent, grandparent, child, grandchild, sibling, aunt/uncle, niece/nephew; age 18+, resident citizen or PR.')}${state.spouse?check('adaptSpouseStudy','Spouse: 2 academic years of qualifying Canadian study')+check('adaptSpouseWork','Spouse: 1 year of authorized full-time Canadian work'):''}<p class="hint">Spouse language CLB/NCLC 4+ and arranged employment are counted automatically when applicable.</p></details><h3 class="subheading">Federal Skilled Trades (FST)</h3><div class="fields">${tri('tradeWork','At least 2 years of qualifying trade work in the last 5 years?','3,120 paid hours over at least 2 years in the same eligible NOC: major groups 72 (not 726), 73, 82, 83, 92, 93 (not 932), minor group 6320 or unit 62200. Meet NOC duties and job requirements; qualified to practise where work was gained; student work excluded.')}${tri('tradeOffer','Qualifying full-time trade job offer for at least 1 year?','Must satisfy IRCC’s valid-offer rules, including applicable LMIA or exemption conditions. A Canadian trade certificate can satisfy this requirement instead.')}</div><p class="hint">All pathways remain subject to admissibility and document verification. Special public-policy exceptions require individual review.</p><button type="button" class="reset" id="reset">Reset profile</button></section>`;
}
function results(){const r=system.calculate(state),e=system.eligibility(state);$('total').textContent=r.total;$('total').setAttribute('aria-label',`${r.total} CRS points`);$('language-choice').textContent=r.hasLanguage?`${r.first} selected as your first official language. Best CRS combination applied.`:'No complete, valid language test results selected.';
const row=(name,value)=>`<div class="break-row"><span>${name}</span><b>${value}</b></div>`,detail=obj=>Object.entries(obj).map(([k,v])=>`<div class="detail"><span>${k}</span><b>${v}</b></div>`).join('');
$('breakdown').innerHTML=row('Core / human capital',r.coreTotal)+row('Spouse factors',r.spouseTotal)+row('Skill transferability',r.transfer)+row('Additional points',r.additional)+`<details><summary>See point-by-point breakdown</summary>${detail(r.core)}<p>Spouse</p>${detail(r.spouseDetail)}<p>Transferability before caps</p>${detail(r.transferDetail)}<p>Education and foreign-work groups: 50 each. Combined transferability: 100.</p><p>Additional before 600 cap</p>${detail(r.additionalDetail)}<p>English first: ${r.alternatives.English} · French first: ${r.alternatives.French}. Ties use English.</p></details>`;
$('score-track').innerHTML=[r.coreTotal,r.spouseTotal,r.transfer,r.additional].map((v,i)=>`<span style="width:${v/12}%;background:${['#daef9a','#a8d9bb','#80b7a6','#e9dd9a'][i]}"></span>`).join('');
$('pathway-results').innerHTML=e.programs.map(p=>`<article class="pathway"><div class="pathway-head"><h3>${p.id} <span class="hint">/ ${p.name}</span></h3><span class="status ${p.status==='Likely eligible'?'pass':''}">${p.status}</span></div><ul>${p.checks.map(([name,ok])=>`<li>${ok===null?'?':ok?'✓':'×'} ${name}${ok===null?' — please confirm':''}</li>`).join('')}</ul>${p.id==='FSW'?`<details><summary>FSW selection points: ${e.fsw.total} / 100</summary>${Object.entries(e.fsw.detail).map(([k,v])=>`<div class="break-row"><span>${k}</span><b>${v}</b></div>`).join('')}</details>`:''}<a href="${p.url}" target="_blank" rel="noopener">Official ${p.id} requirements ↗</a></article>`).join('');}
function render(){form();results();}
$('profile-form').addEventListener('submit',e=>e.preventDefault());
function updateNumeric(t){
 const key=t.dataset.key;
 if(t.value===''||!t.validity.valid)return;
 state[key]=Number(t.value);
 document.querySelectorAll(`[data-key="${key}"]`).forEach(input=>{if(input!==t)input.value=t.value;});
 if(key!=='age'){const items=years(Number(t.max)),label=items[state[key]][1];$(`${key}-value`).textContent=label;t.setAttribute('aria-valuetext',label);}
 results();
}
function updateScore(t){
 const key=t.dataset.language,i=Number(t.dataset.score),l=state[key];
 l.scores[i]=t.value;applyScores(l);
 const level=convertScore(l.test,i,t.value);
 document.querySelectorAll(`[data-language="${key}"][data-score="${i}"]`).forEach(input=>{if(input!==t){if(input.type==='number'||level!==null)input.value=t.value;}if(input.type==='number')input.setAttribute('aria-invalid',String(t.value!==''&&level===null));});
 $(`${key}-benchmark-${i}`).textContent=benchmarkText(level,key.toLowerCase().includes('french'));
 $(`${key}-completion`).textContent=l.complete?'All four scores converted. Language points included.':'Complete all four scores to include this language in your estimate.';
 results();
}
$('profile-form').addEventListener('input',e=>{const t=e.target;if(t.id==='occupation-search'){occupationQuery=t.value;chosenOccupation=null;state.cecTeer='unknown';$('cecTeer').value='unknown';$('occupation-selected').innerHTML='';showOccupations();results();}else if(t.dataset.score!==undefined)updateScore(t);else if(t.dataset.key&&(t.type==='range'||t.type==='number'))updateNumeric(t);});
$('profile-form').addEventListener('change',e=>{
 const t=e.target,key=t.dataset.key,lang=t.dataset.language;
 if(t.dataset.score!==undefined||t.type==='range'||t.type==='number')return;
 if(lang&&t.dataset.mode==='test'){
  state[lang]={test:t.value,scores:['','','',''],levels:[0,0,0,0],tested:false,complete:false};
  const title={english:'English',french:'French',spouseEnglish:'Spouse · English',spouseFrench:'Spouse · French'}[lang];
  $(`language-${lang}`).outerHTML=language(lang,title);
  document.querySelector(`[data-language="${lang}"][data-mode="test"]`).focus({preventScroll:true});
 }else if(key){state[key]=t.type==='checkbox'?t.checked:typeof state[key]==='boolean'?t.value==='true':typeof state[key]==='number'?Number(t.value):t.value;if(key==='spouse')form();if(key==='cecTeer'){chosenOccupation=null;occupationQuery='';$('occupation-search').value='';$('occupation-selected').innerHTML='';closeOccupations();}}
 results();
});
$('profile-form').addEventListener('click',e=>{if(e.target.id==='reset'){state=system.defaults();chosenOccupation=null;occupationQuery='';render();$('profile').scrollIntoView({behavior:'smooth'});}});
$('profile-form').addEventListener('pointerdown',e=>{if(e.target.closest('[data-occupation]'))e.preventDefault();});
$('profile-form').addEventListener('focusin',e=>{if(e.target.id==='occupation-search')showOccupations();});
$('profile-form').addEventListener('click',e=>{const option=e.target.closest('[data-occupation]');if(option)chooseOccupation(Number(option.dataset.occupation));});
$('profile-form').addEventListener('keydown',e=>{
 if(e.target.id!=='occupation-search')return;
 if(e.key==='Escape'){closeOccupations();return;}
 if(e.key==='Enter'){e.preventDefault();if(activeOccupation>=0)chooseOccupation(activeOccupation);return;}
 if(!['ArrowDown','ArrowUp'].includes(e.key))return;e.preventDefault();if($('occupation-options').hidden)showOccupations();if(!occupationMatches.length)return;
 activeOccupation=(activeOccupation+(e.key==='ArrowDown'?1:-1)+occupationMatches.length)%occupationMatches.length;
 $('occupation-search').setAttribute('aria-activedescendant',`occupation-option-${activeOccupation}`);
 document.querySelectorAll('[data-occupation]').forEach((option,i)=>option.setAttribute('aria-selected',String(i===activeOccupation)));
 $(`occupation-option-${activeOccupation}`).scrollIntoView({block:'nearest'});
});
document.addEventListener('click',e=>{if(!e.target.closest('.occupation-picker'))closeOccupations();});
$('profile-form').addEventListener('focusout',e=>{if(e.target.id==='occupation-search'&&!e.relatedTarget?.closest('.occupation-picker'))closeOccupations();});
fetch('./noc-2021.json').then(r=>{if(!r.ok)throw new Error('NOC unavailable');return r.json();}).then(data=>{occupationData=data;occupationLoad='ready';if(document.activeElement?.id==='occupation-search')showOccupations();}).catch(()=>{occupationLoad='error';if(document.activeElement?.id==='occupation-search')showOccupations();});
$('source-links').innerHTML=Object.entries(system.sources).map(([k,v])=>`<a href="${v}" target="_blank" rel="noopener">${k} ↗</a>`).join('')+'<span>Reviewed September 16, 2026</span>';
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'read_express_entry_estimate',description:'Read the current visible CRS estimate and pathway screening without changing the profile.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {score:system.calculate(state),eligibility:system.eligibility(state)};}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
